export interface ProblemModalContextValue {
  activeProblem: ProblemDetail | null;
  triggerRef: RefObject<HTMLElement | null>;
  openProblemModal: (problem: ProblemDetail, triggerElement?: HTMLElement | null) => void;
  closeProblemModal: () => void;
}

const ProblemModalContext = createContext<ProblemModalContextValue | null>(null);

export function ProblemModalProvider({ children }: { children: ReactNode }) {
  const [activeProblem, setActiveProblem] = useState<ProblemDetail | null>(null);
  const triggerRef = useRef<HTMLElement | null>(null);

  const openProblemModal = useCallback((problem: ProblemDetail, triggerElement?: HTMLElement | null) => {
    const fallbackActive = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    triggerRef.current = triggerElement ?? fallbackActive;
    setActiveProblem(problem);
  }, []);

  const closeProblemModal = useCallback(() => {
    setActiveProblem(null);
  }, []);

  const value = useMemo<ProblemModalContextValue>(
    () => ({
      activeProblem,
      triggerRef,
      openProblemModal,
      closeProblemModal,
    }),
    [activeProblem, openProblemModal, closeProblemModal],
  );

  return <ProblemModalContext.Provider value={value}>{children}</ProblemModalContext.Provider>;
}

